def count_calls(fn):
    fn.calls = 0
    def wrapper(*a, **k):
        fn.calls += 1
        return fn(*a, **k)
    wrapper.calls = 0
    return wrapper

@count_calls
def greet():
    return "hi"

greet()
greet()
print(greet.calls)

