class A:
    def who(self): return 'A'
class B(A):
    def who(self): return 'B' + super().who()
class C(A):
    def who(self): return 'C' + super().who()
class D(B, C):
    pass

print(D().who(), [k.__name__ for k in D.__mro__][:4])

order = []
class Base:
    def __init__(self, **kw): order.append(('Base', sorted(kw)))
class L(Base):
    def __init__(self, a=None, **kw): order.append('L'); super().__init__(**kw)
class R(Base):
    def __init__(self, b=None, **kw): order.append('R'); super().__init__(**kw)
class Both(L, R):
    def __init__(self, **kw): order.append('Both'); super().__init__(**kw)

Both(a=1, b=2, c=3)
print(order)

def f():
    try:
        raise ValueError('first')
    except ValueError:
        raise KeyError('second')

try:
    f()
except KeyError as e:
    print(type(e).__name__, type(e.__context__).__name__, e.__cause__, e.args[0])

def build():
    fns = []
    for i in range(3):
        fns.append(lambda: i)
    i = 99
    return fns

def build_bound():
    return [lambda i=i: i for i in range(3)]

print([f() for f in build()], [f() for f in build_bound()])
